import{_ as o,a0 as s,w as p,s as u,ao as n,I as a,x as t,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"什麼是 CI/CD？ | LCTT x X-CMD","titleTemplate":false,"description":"什麼是 CI/CD？ | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什麼是 CI/CD？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什麼是 CI/CD？ | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180806 What is CI-CD","title":"什麼是 CI/CD？","tag":"201808","desc":""},"relativePath":"201808/20180806 What is CI-CD.md","filePath":"[post].md"}'),d={name:"201808/20180806 What is CI-CD.md"};function b(f,r,y,m,C,h){const l=s("Link");return p(),u("div",null,[r[57]||(r[57]=n('<h1 id="什麼是-ci-cd" tabindex="-1">什麼是 CI/CD？ <a class="header-anchor" href="#什麼是-ci-cd" aria-label="Permalink to “什麼是 CI/CD？”">​</a></h1><p>在軟件開發中經常會提到<ruby>持續集成<rt>Continuous Integration</rt></ruby>（CI）和<ruby>持續交付<rt>Continuous Delivery</rt></ruby>（CD）這幾個術語。但它們真正的意思是什麼呢？</p><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/fail_progress_cycle_momentum_arrow.png?itok=q-ZFa_Eh" alt=""></p><p>在談論軟件開發時，經常會提到<ruby>持續集成<rt>Continuous Integration</rt></ruby>（CI）和<ruby>持續交付<rt>Continuous Delivery</rt></ruby>（CD）這幾個術語。但它們真正的意思是什麼呢？在本文中，我將解釋這些和相關術語背後的含義和意義，例如<ruby>持續測試<rt>Continuous Testing</rt></ruby>和<ruby>持續部署<rt>Continuous Deployment</rt></ruby>。</p><h3 id="概覽" tabindex="-1">概覽 <a class="header-anchor" href="#概覽" aria-label="Permalink to “概覽”">​</a></h3><p>工廠裏的裝配線以快速、自動化、可重複的方式從原材料生產出消費品。同樣，軟件交付管道以快速、自動化和可重複的方式從源代碼生成發佈版本。如何完成這項工作的總體設計稱為“持續交付”（CD）。啓動裝配線的過程稱為“持續集成”（CI）。確保質量的過程稱為“持續測試”，將最終產品提供給用户的過程稱為“持續部署”。一些專家讓這一切簡單、順暢、高效地運行，這些人被稱為<ruby>運維開發<rt>DevOps</rt></ruby>踐行者。</p><h3 id="持續-是什麼意思" tabindex="-1">“持續”是什麼意思？ <a class="header-anchor" href="#持續-是什麼意思" aria-label="Permalink to ““持續”是什麼意思？”">​</a></h3><p>“持續”用於描述遵循我在此提到的許多不同流程實踐。這並不意味着“一直在運行”，而是“隨時可運行”。在軟件開發領域，它還包括幾個核心概念/最佳實踐。這些是：</p><ul><li><strong>頻繁發佈</strong>：持續實踐背後的目標是能夠頻繁地交付高質量的軟件。此處的交付頻率是可變的，可由開發團隊或公司定義。對於某些產品，一季度、一個月、一週或一天交付一次可能已經足夠頻繁了。對於另一些來説，一天可能需要多次交付也是可行的。所謂持續也有“偶爾、按需”的方面。最終目標是相同的：在可重複、可靠的過程中為最終用户提供高質量的軟件更新。通常，這可以通過很少甚至無需用户的交互或掌握的知識來完成（想想設備更新）。</li><li><strong>自動化流程</strong>：實現此頻率的關鍵是用自動化流程來處理軟件生產中的方方面面。這包括構建、測試、分析、版本控制，以及在某些情況下的部署。</li><li><strong>可重複</strong>：如果我們使用的自動化流程在給定相同輸入的情況下始終具有相同的行為，則這個過程應該是可重複的。也就是説，如果我們把某個歷史版本的代碼作為輸入，我們應該得到對應相同的可交付產出。這也假設我們有相同版本的外部依賴項（即我們不創建該版本代碼使用的其它交付物）。理想情況下，這也意味着可以對管道中的流程進行版本控制和重建（請參閲稍後的 DevOps 討論）。</li><li><strong>快速迭代</strong>：“快速”在這裏是個相對術語，但無論軟件更新/發佈的頻率如何，預期的持續過程都會以高效的方式將源代碼轉換為交付物。自動化負責大部分工作，但自動化處理的過程可能仍然很慢。例如，對於每天需要多次發佈候選版更新的產品來説，一輪<ruby>集成測試<rt>integrated testing</rt></ruby>下來耗時就要大半天可能就太慢了。</li></ul><h3 id="什麼是-持續交付管道" tabindex="-1">什麼是“持續交付管道”？ <a class="header-anchor" href="#什麼是-持續交付管道" aria-label="Permalink to “什麼是“持續交付管道”？”">​</a></h3><p>將源代碼轉換為可發佈產品的多個不同的<ruby>任務<rt>task</rt></ruby>和<ruby>作業<rt>job</rt></ruby>通常串聯成一個軟件“管道”，一個自動流程成功完成後會啓動管道中的下一個流程。這些管道有許多不同的叫法，例如持續交付管道、部署管道和軟件開發管道。大體上講，程序管理者在管道執行時管理管道各部分的定義、運行、監控和報告。</p><h3 id="持續交付管道是如何工作的" tabindex="-1">持續交付管道是如何工作的？ <a class="header-anchor" href="#持續交付管道是如何工作的" aria-label="Permalink to “持續交付管道是如何工作的？”">​</a></h3><p>軟件交付管道的實際實現可以有很大不同。有許多程序可用在管道中，用於源代碼跟蹤、構建、測試、指標採集，版本管理等各個方面。但整體工作流程通常是相同的。單個業務流程/工作流應用程序管理整個管道，每個流程作為獨立的作業運行或由該應用程序進行階段管理。通常，在業務流程中，這些獨立作業是以應用程序可理解並可作為工作流程管理的語法和結構定義的。</p><p>這些作業被用於一個或多個功能（構建、測試、部署等）。每個作業可能使用不同的技術或多種技術。關鍵是作業是自動化的、高效的，並且可重複的。如果作業成功，則工作流管理器將觸發管道中的下一個作業。如果作業失敗，工作流管理器會向開發人員、測試人員和其他人發出警報，以便他們儘快糾正問題。這個過程是自動化的，所以比手動運行一組過程可更快地找到錯誤。這種快速排錯稱為<ruby>快速失敗<rt>fail fast</rt></ruby>，並且在抵達管道端點方面同樣有價值。</p><h3 id="快速失敗-是什麼意思" tabindex="-1">“快速失敗”是什麼意思？ <a class="header-anchor" href="#快速失敗-是什麼意思" aria-label="Permalink to ““快速失敗”是什麼意思？”">​</a></h3><p>管道的工作之一就是快速處理變更。另一個是監視創建發佈的不同任務/作業。由於編譯失敗或測試未通過的代碼可以阻止管道繼續運行，因此快速通知用户此類情況非常重要。快速失敗指的是在管道流程中儘快發現問題並快速通知用户的方式，這樣可以及時修正問題並重新提交代碼以便使管道再次運行。通常在管道流程中可通過查看歷史記錄來確定是誰做了那次修改並通知此人及其團隊。</p><h3 id="所有持續交付管道都應該被自動化嗎" tabindex="-1">所有持續交付管道都應該被自動化嗎？ <a class="header-anchor" href="#所有持續交付管道都應該被自動化嗎" aria-label="Permalink to “所有持續交付管道都應該被自動化嗎？”">​</a></h3><p>管道的幾乎所有部分都是應該自動化的。對於某些部分，有一些人為干預/互動的地方可能是有意義的。一個例子可能是<ruby>用户驗收測試<rt>user-acceptance testing</rt></ruby>（讓最終用户試用軟件並確保它能達到他們想要/期望的水平）。另一種情況可能是部署到生產環境時用户希望擁有更多的人為控制。當然，如果代碼不正確或不能運行，則需要人工干預。</p><p>有了對“持續”含義理解的背景，讓我們看看不同類型的持續流程以及它們在軟件管道上下文中的含義。</p><h3 id="什麼是-持續集成" tabindex="-1">什麼是“持續集成”？ <a class="header-anchor" href="#什麼是-持續集成" aria-label="Permalink to “什麼是“持續集成”？”">​</a></h3><p>持續集成（CI）是在源代碼變更後自動檢測、拉取、構建和（在大多數情況下）進行單元測試的過程。持續集成是啓動管道的環節（儘管某些預驗證 —— 通常稱為<ruby>上線前檢查<rt>pre-flight checks</rt></ruby> —— 有時會被歸在持續集成之前）。</p><p>持續集成的目標是快速確保開發人員新提交的變更是好的，並且適合在代碼庫中進一步使用。</p><h3 id="持續集成是如何工作的" tabindex="-1">持續集成是如何工作的？ <a class="header-anchor" href="#持續集成是如何工作的" aria-label="Permalink to “持續集成是如何工作的？”">​</a></h3><p>持續集成的基本思想是讓一個自動化過程監測一個或多個源代碼倉庫是否有變更。當變更被推送到倉庫時，它會監測到更改、下載副本、構建並運行任何相關的單元測試。</p><h3 id="持續集成如何監測變更" tabindex="-1">持續集成如何監測變更？ <a class="header-anchor" href="#持續集成如何監測變更" aria-label="Permalink to “持續集成如何監測變更？”">​</a></h3>',25)),a("p",null,[r[1]||(r[1]=t("目前，監測程序通常是像 ",-1)),e(l,{href:"https://jenkins.io"},{default:i(()=>[...r[0]||(r[0]=[t("Jenkins",-1)])]),_:1}),r[2]||(r[2]=t(" 這樣的應用程序，它還協調管道中運行的所有（或大多數）進程，監視變更是其功能之一。監測程序可以以幾種不同方式監測變更。這些包括：",-1))]),r[58]||(r[58]=n('<ul><li><strong>輪詢</strong>：監測程序反覆詢問代碼管理系統，“代碼倉庫裏有什麼我感興趣的新東西嗎？”當代碼管理系統有新的變更時，監測程序會“喚醒”並完成其工作以獲取新代碼並構建/測試它。</li><li><strong>定期</strong>：監測程序配置為定期啓動構建，無論源碼是否有變更。理想情況下，如果沒有變更，則不會構建任何新內容，因此這不會增加額外的成本。</li><li><strong>推送</strong>：這與用於代碼管理系統檢查的監測程序相反。在這種情況下，代碼管理系統被配置為提交變更到倉庫時將“推送”一個通知到監測程序。最常見的是，這可以以 webhook 的形式完成 —— 在新代碼被推送時一個<ruby>掛勾<rt>hook</rt></ruby>的程序通過互聯網向監測程序發送通知。為此，監測程序必須具有可以通過網絡接收 webhook 信息的開放端口。</li></ul><h3 id="什麼是-預檢查-又稱-上線前檢查" tabindex="-1">什麼是“預檢查”（又稱“上線前檢查”）？ <a class="header-anchor" href="#什麼是-預檢查-又稱-上線前檢查" aria-label="Permalink to “什麼是“預檢查”（又稱“上線前檢查”）？”">​</a></h3><p>在將代碼引入倉庫並觸發持續集成之前，可以進行其它驗證。這遵循了最佳實踐，例如<ruby>測試構建<rt>test build</rt></ruby>和<ruby>代碼審查<rt>code review</rt></ruby>。它們通常在代碼引入管道之前構建到開發過程中。但是一些管道也可能將它們作為其監控流程或工作流的一部分。</p>',3)),a("p",null,[r[5]||(r[5]=t("例如，一個名為 ",-1)),e(l,{href:"https://www.gerritcodereview.com"},{default:i(()=>[...r[3]||(r[3]=[t("Gerrit",-1)])]),_:1}),r[6]||(r[6]=t(" 的工具允許在開發人員推送代碼之後但在允許進入（",-1)),e(l,{href:"https://opensource.com/resources/what-is-git"},{default:i(()=>[...r[4]||(r[4]=[t("Git",-1)])]),_:1}),r[7]||(r[7]=t(" 遠程）倉庫之前進行正式的代碼審查、驗證和測試構建。Gerrit 位於開發人員的工作區和 Git 遠程倉庫之間。它會“接收”來自開發人員的推送，並且可以執行通過/失敗驗證以確保它們在被允許進入倉庫之前的檢查是通過的。這可以包括檢測新變更並啓動構建測試（CI 的一種形式）。它還允許開發者在那時進行正式的代碼審查。這種方式有一種額外的可信度評估機制，即當變更的代碼被合併到代碼庫中時不會破壞任何內容。",-1))]),r[59]||(r[59]=n('<h3 id="什麼是-單元測試" tabindex="-1">什麼是“單元測試”？ <a class="header-anchor" href="#什麼是-單元測試" aria-label="Permalink to “什麼是“單元測試”？”">​</a></h3><p>單元測試（也稱為“提交測試”），是由開發人員編寫的小型的專項測試，以確保新代碼獨立工作。“獨立”這裏意味着不依賴或調用其它不可直接訪問的代碼，也不依賴外部數據源或其它模組。如果運行代碼需要這樣的依賴關係，那麼這些資源可以用<ruby>模擬<rt>mock</rt></ruby>來表示。模擬是指使用看起來像資源的<ruby>代碼存根<rt>code stub</rt></ruby>，可以返回值，但不實現任何功能。</p><p>在大多數組織中，開發人員負責創建單元測試以證明其代碼正確。事實上，一種稱為<ruby>測試驅動開發<rt>test-driven develop</rt></ruby>（TDD）的模型要求將首先設計單元測試作為清楚地驗證代碼功能的基礎。因為這樣的代碼可以更改速度快且改動量大，所以它們也必須執行很快。</p>',3)),a("p",null,[r[9]||(r[9]=t("由於這與持續集成工作流有關，因此開發人員在本地工作環境中編寫或更新代碼，並通單元測試來確保新開發的功能或方法正確。通常，這些測試採用斷言形式，即函數或方法的給定輸入集產生給定的輸出集。它們通常進行測試以確保正確標記和處理出錯條件。有很多單元測試框架都很有用，例如用於 Java 開發的 ",-1)),e(l,{href:"https://junit.org/junit5/"},{default:i(()=>[...r[8]||(r[8]=[t("JUnit",-1)])]),_:1}),r[10]||(r[10]=t("。",-1))]),r[60]||(r[60]=n('<h3 id="什麼是-持續測試" tabindex="-1">什麼是“持續測試”？ <a class="header-anchor" href="#什麼是-持續測試" aria-label="Permalink to “什麼是“持續測試”？”">​</a></h3><p>持續測試是指在代碼通過持續交付管道時運行擴展範圍的自動化測試的實踐。單元測試通常與構建過程集成，作為持續集成階段的一部分，並專注於和其它與之交互的代碼隔離的測試。</p><p>除此之外，可以有或者應該有各種形式的測試。這些可包括：</p><ul><li><strong>集成測試</strong> 驗證組件和服務組合在一起是否正常。</li><li><strong>功能測試</strong> 驗證產品中執行功能的結果是否符合預期。</li><li><strong>驗收測試</strong> 根據可接受的標準驗證產品的某些特徵。如性能、可伸縮性、抗壓能力和容量。</li></ul><p>所有這些可能不存在於自動化的管道中，並且一些不同類型的測試分類界限也不是很清晰。但是，在交付管道中持續測試的目標始終是相同的：通過持續的測試級別證明代碼的質量可以在正在進行的發佈中使用。在持續集成快速的原則基礎上，第二個目標是快速發現問題並提醒開發團隊。這通常被稱為快速失敗。</p><h3 id="除了測試之外-還可以對管道中的代碼進行哪些其它類型的驗證" tabindex="-1">除了測試之外，還可以對管道中的代碼進行哪些其它類型的驗證？ <a class="header-anchor" href="#除了測試之外-還可以對管道中的代碼進行哪些其它類型的驗證" aria-label="Permalink to “除了測試之外，還可以對管道中的代碼進行哪些其它類型的驗證？”">​</a></h3>',6)),a("p",null,[r[12]||(r[12]=t("除了測試是否通過之外，還有一些應用程序可以告訴我們測試用例執行（覆蓋）的源代碼行數。這是一個可以衡量代碼量指標的例子。這個指標稱為",-1)),r[13]||(r[13]=a("ruby",null,[t("代碼覆蓋率"),a("rt",null,"code-coverage")],-1)),r[14]||(r[14]=t("，可以通過工具（例如用於 Java 的 ",-1)),e(l,{href:"https://www.eclemma.org/jacoco/"},{default:i(()=>[...r[11]||(r[11]=[t("JaCoCo",-1)])]),_:1}),r[15]||(r[15]=t("）進行統計。",-1))]),a("p",null,[r[17]||(r[17]=t("還有很多其它類型的指標統計，例如代碼行數、複雜度以及代碼結構對比分析等。諸如 ",-1)),e(l,{href:"https://www.sonarqube.org/"},{default:i(()=>[...r[16]||(r[16]=[t("SonarQube",-1)])]),_:1}),r[18]||(r[18]=t(" 之類的工具可以檢查源代碼並計算這些指標。此外，用户還可以為他們可接受的“合格”範圍的指標設置閾值。然後可以在管道中針對這些閾值設置一個檢查，如果結果不在可接受範圍內，則流程終端上。SonarQube 等應用程序具有很高的可配置性，可以設置僅檢查團隊感興趣的內容。",-1))]),r[61]||(r[61]=n('<h3 id="什麼是-持續交付" tabindex="-1">什麼是“持續交付”？ <a class="header-anchor" href="#什麼是-持續交付" aria-label="Permalink to “什麼是“持續交付”？”">​</a></h3><p>持續交付（CD）通常是指整個流程鏈（管道），它自動監測源代碼變更並通過構建、測試、打包和相關操作運行它們以生成可部署的版本，基本上沒有任何人為干預。</p><p>持續交付在軟件開發過程中的目標是自動化、效率、可靠性、可重複性和質量保障（通過持續測試）。</p><p>持續交付包含持續集成（自動檢測源代碼變更、執行構建過程、運行單元測試以驗證變更），持續測試（對代碼運行各種測試以保障代碼質量），和（可選）持續部署（通過管道發佈版本自動提供給用户）。</p><h3 id="如何在管道中識別-跟蹤多個版本" tabindex="-1">如何在管道中識別/跟蹤多個版本？ <a class="header-anchor" href="#如何在管道中識別-跟蹤多個版本" aria-label="Permalink to “如何在管道中識別/跟蹤多個版本？”">​</a></h3><p>版本控制是持續交付和管道的關鍵概念。持續意味着能夠經常集成新代碼並提供更新版本。但這並不意味着每個人都想要“最新、最好的”。對於想要開發或測試已知的穩定版本的內部團隊來説尤其如此。因此，管道創建並輕鬆存儲和訪問的這些版本化對象非常重要。</p><p>在管道中從源代碼創建的對象通常可以稱為<ruby>工件<rt>artifact</rt></ruby>。工件在構建時應該有應用於它們的版本。將版本號分配給工件的推薦策略稱為<ruby>語義化版本控制<rt>semantic versioning</rt></ruby>。（這也適用於從外部源引入的依賴工件的版本。）</p><p>語義版本號有三個部分：<ruby>主要版本<rt>major</rt></ruby>、<ruby>次要版本<rt>minor</rt></ruby> 和 <ruby>補丁版本<rt>patch</rt></ruby>。（例如，1.4.3 反映了主要版本 1，次要版本 4 和補丁版本 3。）這個想法是，其中一個部分的更改表示工件中的更新級別。主要版本僅針對不兼容的 API 更改而遞增。當以<ruby>向後兼容<rt>backward-compatible</rt></ruby>的方式添加功能時，次要版本會增加。當進行向後兼容的版本 bug 修復時，補丁版本會增加。這些是建議的指導方針，但只要團隊在整個組織內以一致且易於理解的方式這樣做，團隊就可以自由地改變這種方法。例如，每次為發佈完成構建時增加的數字可以放在補丁字段中。</p><h3 id="如何-分銷-工件" tabindex="-1">如何“分銷”工件？ <a class="header-anchor" href="#如何-分銷-工件" aria-label="Permalink to “如何“分銷”工件？”">​</a></h3>',9)),a("p",null,[r[20]||(r[20]=t("團隊可以為工件分配",-1)),r[21]||(r[21]=a("ruby",null,[t("分銷"),a("rt",null,"promotion")],-1)),r[22]||(r[22]=t("級別以指示適用於測試、生產等環境或用途。有很多方法。可以用 Jenkins 或 ",-1)),e(l,{href:"https://jfrog.com/artifactory/"},{default:i(()=>[...r[19]||(r[19]=[t("Artifactory",-1)])]),_:1}),r[23]||(r[23]=t(" 等應用程序進行分銷。或者一個簡單的方案可以在版本號字符串的末尾添加標籤。例如，",-1)),r[24]||(r[24]=a("code",null,"-snapshot",-1)),r[25]||(r[25]=t(" 可以指示用於構建工件的代碼的最新版本（快照）。可以使用各種分銷策略或工具將工件“提升”到其它級別，例如 ",-1)),r[26]||(r[26]=a("code",null,"-milestone",-1)),r[27]||(r[27]=t(" 或 ",-1)),r[28]||(r[28]=a("code",null,"-production",-1)),r[29]||(r[29]=t("，作為工件穩定性和完備性版本的標記。",-1))]),r[62]||(r[62]=a("h3",{id:"如何存儲和訪問多個工件版本",tabindex:"-1"},[t("如何存儲和訪問多個工件版本？ "),a("a",{class:"header-anchor",href:"#如何存儲和訪問多個工件版本","aria-label":"Permalink to “如何存儲和訪問多個工件版本？”"},"​")],-1)),a("p",null,[r[31]||(r[31]=t("從源代碼構建的版本化工件可以通過管理",-1)),r[32]||(r[32]=a("ruby",null,[t("工件倉庫"),a("rt",null,"artifact repository")],-1)),r[33]||(r[33]=t("的應用程序進行存儲。工件倉庫就像構建工件的版本控制工具一樣。像 Artifactory 或 ",-1)),e(l,{href:"https://www.sonatype.com/nexus-repository-sonatype"},{default:i(()=>[...r[30]||(r[30]=[t("Nexus",-1)])]),_:1}),r[34]||(r[34]=t(" 這類應用可以接受版本化工件，存儲和跟蹤它們，並提供檢索的方法。",-1))]),r[63]||(r[63]=n('<p>管道用户可以指定他們想要使用的版本，並在這些版本中使用管道。</p><h3 id="什麼是-持續部署" tabindex="-1">什麼是“持續部署”？ <a class="header-anchor" href="#什麼是-持續部署" aria-label="Permalink to “什麼是“持續部署”？”">​</a></h3><p>持續部署（CD）是指能夠自動提供持續交付管道中發佈版本給最終用户使用的想法。根據用户的安裝方式，可能是在雲環境中自動部署、app 升級（如手機上的應用程序）、更新網站或只更新可用版本列表。</p><p>這裏的一個重點是，僅僅因為可以進行持續部署並不意味着始終部署來自管道的每組可交付成果。它實際上指，通過管道每套可交付成果都被證明是“可部署的”。這在很大程度上是由持續測試的連續級別完成的（參見本文中的持續測試部分）。</p><p>管道構建的發佈成果是否被部署可以通過人工決策，或利用在完全部署之前“試用”發佈的各種方法來進行控制。</p><h3 id="在完全部署到所有用户之前-有哪些方法可以測試部署" tabindex="-1">在完全部署到所有用户之前，有哪些方法可以測試部署？ <a class="header-anchor" href="#在完全部署到所有用户之前-有哪些方法可以測試部署" aria-label="Permalink to “在完全部署到所有用户之前，有哪些方法可以測試部署？”">​</a></h3><p>由於必須回滾/撤消對所有用户的部署可能是一種代價高昂的情況（無論是技術上還是用户的感知），已經有許多技術允許“嘗試”部署新功能並在發現問題時輕鬆“撤消”它們。這些包括：</p><h4 id="藍-綠測試-部署" tabindex="-1">藍/綠測試/部署 <a class="header-anchor" href="#藍-綠測試-部署" aria-label="Permalink to “藍/綠測試/部署”">​</a></h4><p>在這種部署軟件的方法中，維護了兩個相同的主機環境 —— 一個“藍色” 和一個“綠色”。（顏色並不重要，僅作為標識。）對應來説，其中一個是“生產環境”，另一個是“預發佈環境”。</p><p>在這些實例的前面是調度系統，它們充當產品或應用程序的客户“網關”。通過將調度系統指向藍色或綠色實例，可以將客户流量引流到期望的部署環境。通過這種方式，切換指向哪個部署實例（藍色或綠色）對用户來説是快速，簡單和透明的。</p><p>當新版本準備好進行測試時，可以將其部署到非生產環境中。在經過測試和批准後，可以更改調度系統設置以將傳入的線上流量指向它（因此它將成為新的生產站點）。現在，曾作為生產環境實例可供下一次候選發佈使用。</p><p>同理，如果在最新部署中發現問題並且之前的生產實例仍然可用，則簡單的更改可以將客户流量引流回到之前的生產實例 —— 有效地將問題實例“下線”並且回滾到以前的版本。然後有問題的新實例可以在其它區域中修復。</p><h4 id="金絲雀測試-部署" tabindex="-1">金絲雀測試/部署 <a class="header-anchor" href="#金絲雀測試-部署" aria-label="Permalink to “金絲雀測試/部署”">​</a></h4><p>在某些情況下，通過藍/綠髮布切換整個部署可能不可行或不是期望的那樣。另一種方法是為<ruby>金絲雀<rt>canary</rt></ruby>測試/部署。在這種模型中，一部分客户流量被重新引流到新的版本部署中。例如，新版本的搜索服務可以與當前服務的生產版本一起部署。然後，可以將 10％ 的搜索查詢引流到新版本，以在生產環境中對其進行測試。</p><p>如果服務那些流量的新版本沒問題，那麼可能會有更多的流量會被逐漸引流過去。如果仍然沒有問題出現，那麼隨着時間的推移，可以對新版本增量部署，直到 100％ 的流量都調度到新版本。這有效地“更替”了以前版本的服務，並讓新版本對所有客户生效。</p><h4 id="功能開關" tabindex="-1">功能開關 <a class="header-anchor" href="#功能開關" aria-label="Permalink to “功能開關”">​</a></h4><p>對於可能需要輕鬆關掉的新功能（如果發現問題），開發人員可以添加<ruby>功能開關<rt>feature toggles</rt></ruby>。這是代碼中的 <code>if-then</code> 軟件功能開關，僅在設置數據值時才激活新代碼。此數據值可以是全局可訪問的位置，部署的應用程序將檢查該位置是否應執行新代碼。如果設置了數據值，則執行代碼；如果沒有，則不執行。</p><p>這為開發人員提供了一個遠程“終止開關”，以便在部署到生產環境後發現問題時關閉新功能。</p><h4 id="暗箱發佈" tabindex="-1">暗箱發佈 <a class="header-anchor" href="#暗箱發佈" aria-label="Permalink to “暗箱發佈”">​</a></h4><p>在<ruby>暗箱發佈<rt>dark launch</rt></ruby>中，代碼被逐步測試/部署到生產環境中，但是用户不會看到更改（因此名稱中有<ruby>暗箱<rt>dark</rt></ruby>一詞）。例如，在生產版本中，網頁查詢的某些部分可能會重定向到查詢新數據源的服務。開發人員可收集此信息進行分析，而不會將有關接口，事務或結果的任何信息暴露給用户。</p><p>這個想法是想獲取候選版本在生產環境負載下如何執行的真實信息，而不會影響用户或改變他們的經驗。隨着時間的推移，可以調度更多負載，直到遇到問題或認為新功能已準備好供所有人使用。實際上功能開關標誌可用於這種暗箱發佈機制。</p><h3 id="什麼是-運維開發" tabindex="-1">什麼是“運維開發”？ <a class="header-anchor" href="#什麼是-運維開發" aria-label="Permalink to “什麼是“運維開發”？”">​</a></h3>',22)),a("p",null,[a("ruby",null,[e(l,{href:"https://opensource.com/resources/devops"},{default:i(()=>[...r[35]||(r[35]=[t("運維開發",-1)])]),_:1}),r[36]||(r[36]=a("rt",null,"DevOps",-1))]),r[37]||(r[37]=t(" 是關於如何使開發和運維團隊更容易合作開發和發佈軟件的一系列想法和推薦的實踐。從歷史上看，開發團隊研發了產品，但沒有像客户那樣以常規、可重複的方式安裝/部署它們。在整個週期中，這組安裝/部署任務（以及其它支持任務）留給運維團隊負責。這經常導致很多混亂和問題，因為運維團隊在後期才開始介入，並且必須在短時間內完成他們的工作。同樣，開發團隊經常處於不利地位 —— 因為他們沒有充分測試產品的安裝/部署功能，他們可能會對該過程中出現的問題感到驚訝。",-1))]),r[64]||(r[64]=a("p",null,"這往往導致開發和運維團隊之間嚴重脱節和缺乏合作。DevOps 理念主張是貫穿整個開發週期的開發和運維綜合協作的工作方式，就像持續交付那樣。",-1)),r[65]||(r[65]=a("h3",{id:"持續交付如何與運維開發相交",tabindex:"-1"},[t("持續交付如何與運維開發相交？ "),a("a",{class:"header-anchor",href:"#持續交付如何與運維開發相交","aria-label":"Permalink to “持續交付如何與運維開發相交？”"},"​")],-1)),r[66]||(r[66]=a("p",null,"持續交付管道是幾個 DevOps 理念的實現。產品開發的後期階段（如打包和部署）始終可以在管道的每次運行中完成，而不是等待產品開發週期中的特定時間。同樣，從開發到部署過程中，開發和運維都可以清楚地看到事情何時起作用，何時不起作用。要使持續交付管道循環成功，不僅要通過與開發相關的流程，還要通過與運維相關的流程。",-1)),r[67]||(r[67]=a("p",null,"説得更遠一些，DevOps 建議實現管道的基礎架構也會被視為代碼。也就是説，它應該自動配置、可跟蹤、易於修改，並在管道發生變化時觸發新一輪運行。這可以通過將管道實現為代碼來完成。",-1)),r[68]||(r[68]=a("h3",{id:"什麼是-管道即代碼",tabindex:"-1"},[t("什麼是“管道即代碼”？ "),a("a",{class:"header-anchor",href:"#什麼是-管道即代碼","aria-label":"Permalink to “什麼是“管道即代碼”？”"},"​")],-1)),a("p",null,[r[39]||(r[39]=a("ruby",null,[t("管道即代碼"),a("rt",null,"pipeline-as-code")],-1)),r[40]||(r[40]=t("是通過編寫代碼創建管道作業/任務的通用術語，就像開發人員編寫代碼一樣。它的目標是將管道實現表示為代碼，以便它可以與代碼一起存儲、評審、跟蹤，如果出現問題並且必須終止管道，則可以輕鬆地重建。有幾個工具允許這樣做，如 ",-1)),e(l,{href:"https://jenkins.io"},{default:i(()=>[...r[38]||(r[38]=[t("Jenkins 2",-1)])]),_:1}),r[41]||(r[41]=t("。",-1))]),r[69]||(r[69]=n('<h3 id="devops-如何影響生產軟件的基礎設施" tabindex="-1">DevOps 如何影響生產軟件的基礎設施？ <a class="header-anchor" href="#devops-如何影響生產軟件的基礎設施" aria-label="Permalink to “DevOps 如何影響生產軟件的基礎設施？”">​</a></h3><p>傳統意義上，管道中使用的各個硬件系統都有配套的軟件（操作系統、應用程序、開發工具等）。在極端情況下，每個系統都是手工設置來定製的。這意味着當系統出現問題或需要更新時，這通常也是一項自定義任務。這種方法違背了持續交付的基本理念，即具有易於重現和可跟蹤的環境。</p><p>多年來，很多應用被開發用於標準化交付（安裝和配置）系統。同樣，<ruby>虛擬機<rt>virtual machine</rt></ruby>被開發為模擬在其它計算機之上運行的計算機程序。這些 VM 要有管理程序才能在底層主機系統上運行，並且它們需要自己的操作系統副本才能運行。</p><p>後來有了<ruby>容器<rt>container</rt></ruby>。容器雖然在概念上與 VM 類似，但工作方式不同。它們只需使用一些現有的操作系統結構來劃分隔離空間，而不需要運行單獨的程序和操作系統的副本。因此，它們的行為類似於 VM 以提供隔離但不需要過多的開銷。</p><p>VM 和容器是根據配置定義創建的，因此可以輕易地銷燬和重建，而不會影響運行它們的主機系統。這允許運行管道的系統也可重建。此外，對於容器，我們可以跟蹤其構建定義文件的更改 —— 就像對源代碼一樣。</p><p>因此，如果遇到 VM 或容器中的問題，我們可以更容易、更快速地銷燬和重建它們，而不是在當前環境嘗試調試和修復。</p><p>這也意味着對管道代碼的任何更改都可以觸發管道新一輪運行（通過 CI），就像對代碼的更改一樣。這是 DevOps 關於基礎架構的核心理念之一。</p><hr>',8)),a("p",null,[r[43]||(r[43]=t("via: ",-1)),e(l,{href:"https://opensource.com/article/18/8/what-cicd"},{default:i(()=>[...r[42]||(r[42]=[t("https://opensource.com/article/18/8/what-cicd",-1)])]),_:1})]),a("p",null,[r[48]||(r[48]=t("作者：",-1)),e(l,{href:"https://opensource.com/users/bclaster"},{default:i(()=>[...r[44]||(r[44]=[t("Brent Laster",-1)])]),_:1}),r[49]||(r[49]=t(" 選題：",-1)),e(l,{href:"https://github.com/lujun9972"},{default:i(()=>[...r[45]||(r[45]=[t("lujun9972",-1)])]),_:1}),r[50]||(r[50]=t(" 譯者：",-1)),e(l,{href:"https://github.com/pityonline"},{default:i(()=>[...r[46]||(r[46]=[t("pityonline",-1)])]),_:1}),r[51]||(r[51]=t(" 校對：",-1)),e(l,{href:"https://github.com/wxy"},{default:i(()=>[...r[47]||(r[47]=[t("wxy",-1)])]),_:1})]),a("p",null,[r[54]||(r[54]=t("本文由 ",-1)),e(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...r[52]||(r[52]=[t("LCTT",-1)])]),_:1}),r[55]||(r[55]=t(" 原創編譯，",-1)),e(l,{href:"https://linux.cn/"},{default:i(()=>[...r[53]||(r[53]=[t("Linux中國",-1)])]),_:1}),r[56]||(r[56]=t(" 榮譽推出",-1))])])}const P=o(d,[["render",b]]);export{k as __pageData,P as default};
